// node check3.mjs <slug> : Überlauf, Lesezeit, Ausschnitte bei 390 px
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const slug = process.argv[2];
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 390, height: 844 } });
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
const r = await p.goto("http://localhost:3100/ratgeber/" + slug, { waitUntil: "load", timeout: 240000 });
await p.waitForTimeout(3000);
try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
const info = await p.evaluate(() => {
  const doc = document.documentElement;
  const breit = [...document.querySelectorAll("body *")].filter((e) => {
    const rr = e.getBoundingClientRect();
    return rr.right > window.innerWidth + 1 && !e.closest(".overflow-x-auto, [class*=overflow-x]");
  }).slice(0, 5).map((e) => e.tagName + "." + (e.className || "").toString().slice(0, 60));
  const lz = (document.body.innerText.match(/\d+\s*Min\.\s*Lesezeit/) || [""])[0];
  const text = document.body.innerText;
  return { scroll: doc.scrollWidth, client: doc.clientWidth, breit, lz, nan: /NaN|undefined|Infinity/.test(text), tables: [...document.querySelectorAll("table")].map((t) => t.getBoundingClientRect().top + window.scrollY) };
});
console.log(r.status(), JSON.stringify(info), fehler.join("\n"));
let i = 0;
for (const y of info.tables) {
  await p.evaluate((yy) => window.scrollTo(0, yy - 120), y);
  await p.waitForTimeout(400);
  await p.screenshot({ path: fileURLToPath(new URL(`./shots/${slug}_t${i++}.png`, import.meta.url)) });
}
await b.close();

